import {
  Box,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  Divider,
  Chip,
} from "@mui/material";
import {
  Dashboard as DashboardIcon,
  TrendingUp as ForecastIcon,
  Assessment as AnalyticsIcon,
  MonitorHeart as MonitorIcon,
  Speed as PerformanceIcon,
  CloudQueue as WeatherIcon,
  ListAlt as DataIcon,
  Settings as SettingsIcon,
  Help as HelpIcon,
} from "@mui/icons-material";
import { NavLink } from "react-router-dom";
import { ROUTES } from "../../routes/routes";
import logo from "../../assets/Eskom-logo-white.gif";

// NEW GROUPING - More logical organization
const navigation = {
  main: [
    {
      title: "Dashboard",
      icon: DashboardIcon,
      path: ROUTES.FORECAST,
      badge: null,
      description: "Overview & KPIs",
    },
  ],
  forecasting: [
    {
      title: "Forecast Generator",
      icon: ForecastIcon,
      path: ROUTES.FORECAST,
      badge: "LIVE",
      description: "Generate predictions",
    },
    {
      title: "Weather Intelligence",
      icon: WeatherIcon,
      path: ROUTES.FORECAST,
      badge: null,
      description: "Weather correlation",
    },
    {
      title: "Forecast Data",
      icon: DataIcon,
      path: ROUTES.FORECAST,
      badge: null,
      description: "Historical data",
    },
  ],
  analytics: [
    {
      title: "Model Performance",
      icon: PerformanceIcon,
      path: ROUTES.MODEL_PERFORMANCE,
      badge: null,
      description: "Accuracy metrics",
    },
    {
      title: "Analytics Dashboard",
      icon: AnalyticsIcon,
      path: ROUTES.MODEL_PERFORMANCE,
      badge: null,
      description: "Detailed analysis",
    },
  ],
  monitoring: [
    {
      title: "System Health",
      icon: MonitorIcon,
      path: ROUTES.INFERENCE,
      badge: null,
      description: "Pipeline status",
    },
    {
      title: "Activity Monitor",
      icon: MonitorIcon,
      path: ROUTES.INFERENCE_MONITORING,
      badge: "NEW",
      description: "Live tracking",
    },
  ],
};

const DashboardSidebar = () => {
  return (
    <Box
      sx={{
        width: 280,
        height: "100vh",
        bgcolor: "#003DA5", // Eskom Blue
        color: "white",
        display: "flex",
        flexDirection: "column",
        borderRight: "1px solid rgba(255, 255, 255, 0.1)",
        position: "sticky",
        top: 0,
      }}
    >
      {/* LOGO & BRANDING */}
      <Box
        sx={{
          p: 3,
          borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
        }}
      >
        <Box
          component="img"
          src={logo}
          alt="Eskom"
          sx={{
            width: "100%",
            maxWidth: 160,
            mb: 1,
          }}
        />
        <Typography
          variant="caption"
          sx={{
            color: "#FFD100", // Eskom Yellow
            fontWeight: 700,
            fontSize: "0.75rem",
            letterSpacing: "0.5px",
          }}
        >
          FORECAST CONTROL CENTER
        </Typography>
      </Box>

      {/* NAVIGATION - Scrollable */}
      <Box
        sx={{
          flex: 1,
          overflow: "auto",
          py: 2,
          "&::-webkit-scrollbar": {
            width: "6px",
          },
          "&::-webkit-scrollbar-track": {
